  // ---------- Riepilogo ----------
  function renderAmount(el, value){
    var neg = value < 0;
    var parts = fmtEUR(Math.abs(value)).split(",");
    el.innerHTML = (neg ? "&minus;" : "") + parts[0] + "<span class='cents'>," + parts[1] + " €</span>";
  }

