  function operationDisplayInfo(op){
    var tagClass, tagLabel, desc, amountClass, sign, amountValue;
    if(op.tipo === "VENDITA"){
      tagClass = "vendita"; tagLabel = "Vendita";
      desc = op.quantita + " pz · " + op.gioco;
      amountClass = "pos"; sign = "+"; amountValue = op.importo;
    } else if(op.tipo === "VINCITA" || (op.tipo === "PAGAMENTO VINCITA" && op.schede && op.schede.length)){
      tagClass = "vincita-scheda"; tagLabel = "Vincita";
      desc = (op.schede && op.schede.length)
        ? op.schede.map(function(s){ return s.quantita + "× " + s.gioco; }).join(", ")
        : (op.gioco || "Biglietto vincente");
      amountClass = "neutral"; sign = "";
      amountValue = 0;
    } else {
      tagClass = "vincita-contanti"; tagLabel = "Riscossione";
      desc = op.gioco ? ("gioco: " + op.gioco) : "";
      amountClass = "neg"; sign = "−"; amountValue = op.importo;
    }
    if(op.note) desc += (desc ? " — " : "") + op.note;
    return { tagClass: tagClass, tagLabel: tagLabel, desc: desc, amountClass: amountClass, sign: sign, amountValue: amountValue };
  }

  function sortedOperations(){
    return state.operations.slice().sort(function(a,b){ return (b.data + (b.ora||"") + b.id) > (a.data + (a.ora||"") + a.id) ? 1 : -1; });
  }

  function fmtDateTime(op){
    return fmtDate(op.data) + (op.ora ? " " + op.ora : "");
  }

  // Il registro a destra mostra solo le operazioni "vive": fatte di recente.
  // Dopo questa finestra di tempo, un'operazione non scompare dai dati - esce
  // solo dal registro in tempo reale, e resta visibile in "Tutte le operazioni".
  var REGISTRO_FINESTRA_MS = 2 * 60 * 60 * 1000; // 2 ore

  function renderOpsList(){
    var opsList = document.getElementById('opsList');
    opsList.innerHTML = "";
    var ora = Date.now();
    var recenti = sortedOperations().filter(function(op){
      return op.ts && (ora - op.ts) <= REGISTRO_FINESTRA_MS;
    });
    if(recenti.length === 0){
      opsList.innerHTML = "<div class='empty-state'>Nessuna operazione nelle ultime 2 ore.<br>Le operazioni più vecchie sono in \u201cTutte le operazioni\u201d qui sotto.</div>";
      return;
    }
    recenti.slice(0, 40).forEach(function(op){
      var info = operationDisplayInfo(op);
      var li = document.createElement('li');
      li.innerHTML =
        "<div class='op-left'><span class='op-tag " + info.tagClass + "'>" + info.tagLabel + "</span><span class='op-desc'>" + info.desc + "</span></div>" +
        "<div style='display:flex;align-items:center;gap:8px;'>" +
          "<span class='op-date'>" + (op.ora || "") + "</span>" +
          "<span class='op-amount " + info.amountClass + "'>" + info.sign + fmtEUR(info.amountValue) + " €</span>" +
          "<button class='op-del' data-id='" + op.id + "' title='Elimina'>\u2715</button>" +
        "</div>";
      opsList.appendChild(li);
    });
  }

  function renderOperazioniComplete(){
    var body = document.getElementById('operazioniCompleteBody');
    if(!body) return;
    body.innerHTML = "";
    var sorted = sortedOperations();
    if(sorted.length === 0){
      body.innerHTML = "<tr><td colspan='5' style='color:var(--ink-soft);padding:10px 0;'>Nessuna operazione registrata ancora.</td></tr>";
      return;
    }
    sorted.forEach(function(op){
      var info = operationDisplayInfo(op);
      var tr = document.createElement('tr');
      tr.innerHTML =
        "<td>" + fmtDateTime(op) + "</td>" +
        "<td><span class='op-tag " + info.tagClass + "'>" + info.tagLabel + "</span></td>" +
        "<td>" + info.desc + "</td>" +
        "<td class='num-col' style='color:" + (info.amountClass === "pos" ? "var(--teal-dark)" : info.amountClass === "neg" ? "var(--red)" : "#8A6C0F") + ";font-weight:600;'>" + info.sign + fmtEUR(info.amountValue) + " €</td>" +
        "<td><button class='op-del' data-id='" + op.id + "' title='Elimina'>\u2715</button></td>";
      body.appendChild(tr);
    });
  }

  async function deleteOperation(id){
    var op = state.operations.find(function(o){ return o.id === id; });
    if(op && op.tipo === "VENDITA"){
      var g = findGame(op.gioco);
      if(g) g.giacenza += Number(op.quantita) || 0; // restore stock if a sale is deleted
      await saveGames();
    }
    if(op && (op.tipo === "VINCITA" || op.tipo === "PAGAMENTO VINCITA") && op.schede && op.schede.length){
      op.schede.forEach(function(s){
        var gs = findGame(s.gioco);
        if(gs) gs.giacenza += Number(s.quantita) || 0; // le schede date in cambio tornano in magazzino
      });
      await saveGames();
    }
    state.operations = state.operations.filter(function(o){ return o.id !== id; });
    await saveOperations();
    renderTiles();
    renderRiepilogo();
    scheduleSbAutoSync();
    showToast("Operazione eliminata");
  }

